import{_ as o,o as a,c as t,a3 as i}from"./chunks/framework.C6m_RRf-.js";const h=JSON.parse('{"title":"版本更新","description":"","frontmatter":{},"headers":[],"relativePath":"update.md","filePath":"update.md","lastUpdated":1789925211000}'),l={name:"update.md"};function s(r,e,c,d,n,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="版本更新" tabindex="-1">版本更新 <a class="header-anchor" href="#版本更新" aria-label="Permalink to &quot;版本更新&quot;">​</a></h1><p>不同部署方式的更新方式也不同，请对号入座。更新部署成功后，请不要忘记同时更新前端的 Twikoo CDN 地址中的 <code>x.x.x</code> 数字版本号，使之与云函数版本号相同，然后部署网站。</p><h2 id="针对腾讯云-cloudbase-部署的更新方式" tabindex="-1">针对腾讯云 CloudBase 部署的更新方式 <a class="header-anchor" href="#针对腾讯云-cloudbase-部署的更新方式" aria-label="Permalink to &quot;针对腾讯云 CloudBase 部署的更新方式&quot;">​</a></h2><p>登录<a href="https://console.cloud.tencent.com/tcb/scf/index" target="_blank" rel="noreferrer">环境 - 云函数</a>，点击 twikoo，点击函数代码，打开 <code>package.json</code> 文件，确认依赖写的是 <code>&quot;twikoo-func&quot;: &quot;latest&quot;</code>（1.x 时代这里写的是固定版本号，建议一并改成 <code>latest</code>，以后升级就不用再改），点击“保存并安装依赖”即可。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果您的云函数是 1.0.0 之前的版本，因为 1.0.0 版本修改了部署步骤，请先参考<a href="#手动部署">手动部署</a>，从第 5 步开始，重新创建云函数，再按照此步骤更新。</p><p>如果升级后出现无法读取评论列表，云函数报错，请在函数编辑页面，删除 <code>node_modules</code> 目录（删除需要半分钟左右，请耐心等待删除完成），再点击保存并安装依赖。如果仍然不能解决，请删除并重新创建 Twikoo 云函数。</p></div><div class="warning custom-block"><p class="custom-block-title">运行时版本</p><p>CloudBase 请将云函数运行时升级到 <strong>Node 20 及以上（推荐 24）</strong>；2.0 产物语法目标为 ES2022，不再兼容 Node 16.13。</p></div><h2 id="针对-vercel-部署的更新方式" tabindex="-1">针对 Vercel 部署的更新方式 <a class="header-anchor" href="#针对-vercel-部署的更新方式" aria-label="Permalink to &quot;针对 Vercel 部署的更新方式&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">不需要改版本号</p><p>一键部署的依赖写的是 <code>twikoo-vercel@latest</code>（见 <a href="https://github.com/twikoojs/twikoo/blob/main/templates/vercel-min/package.json" target="_blank" rel="noreferrer"><code>templates/vercel-min/package.json</code></a>）， 重新部署即可拿到最新稳定版。</p><p>注意 Vercel 默认复用构建缓存，缓存命中时不会重新解析 <code>latest</code>—— <strong>重新部署时取消勾选「Use existing Build Cache」</strong>，否则依赖还是旧的。</p></div><ol><li>进入 <a href="https://vercel.com/dashboard" target="_blank" rel="noreferrer">Vercel 仪表板</a> - twikoo - Deployments</li><li>在最新一次部署右侧点击更多（三个点）- Redeploy</li><li>在弹窗中取消勾选 Use existing Build Cache，点击 Redeploy</li><li>部署完成后访问域名，如果环境配置正确，可以看到“Twikoo 云函数运行正常”的提示</li></ol><h2 id="针对-railway-和-zeabur-部署的更新方式" tabindex="-1">针对 Railway 和 Zeabur 部署的更新方式 <a class="header-anchor" href="#针对-railway-和-zeabur-部署的更新方式" aria-label="Permalink to &quot;针对 Railway 和 Zeabur 部署的更新方式&quot;">​</a></h2><p>模板仓库 <a href="https://github.com/twikoojs/twikoo-zeabur" target="_blank" rel="noreferrer"><code>twikoojs/twikoo-zeabur</code></a> 的依赖写的是 <code>tkserver@latest</code>，<strong>不需要改版本号</strong>。</p><ol><li>登录 Github，找到部署时 fork 到自己账号下的名为 twikoo-zeabur 的仓库，点击 Sync fork 同步上游</li><li>部署会自动触发；如果没有触发、或更新后版本没变，到 Railway / Zeabur 控制台手动重新部署一次</li></ol><div class="tip custom-block"><p class="custom-block-title">如果你的 fork 里写的是固定版本号</p><p>把 <code>package.json</code> 里的 <code>&quot;tkserver&quot;: &quot;x.x.x&quot;</code> 改成 <code>&quot;tkserver&quot;: &quot;latest&quot;</code>，以后就只需要同步 fork 再重新部署。</p></div><h2 id="针对-netlify-部署的更新方式" tabindex="-1">针对 Netlify 部署的更新方式 <a class="header-anchor" href="#针对-netlify-部署的更新方式" aria-label="Permalink to &quot;针对 Netlify 部署的更新方式&quot;">​</a></h2><ol><li>登录 GitHub，找到部署时 fork 到自己账号下的名为 twikoo-netlify 的仓库</li><li>确认 <code>package.json</code> 里的依赖写的是 <code>latest</code>（不是的话改成下面这样）</li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;twikoo-netlify&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;latest&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">2.0 起只需要一个依赖</p><p>1.x 的 <code>twikoo-netlify</code> 复用了 <code>twikoo-vercel</code> 的实现，所以要同时写两个依赖； 2.0 起两者各自独立实现，只留 <code>twikoo-netlify</code> 即可。</p></div><ol start="3"><li>点击 Sync fork 同步上游，然后在 Netlify 控制台 Deploys - Trigger deploy - <strong>Clear cache and deploy site</strong>（清缓存才会重新解析 <code>latest</code>）</li><li>部署会自动触发</li></ol><h2 id="针对-hugging-face-部署的更新方式" tabindex="-1">针对 Hugging Face 部署的更新方式 <a class="header-anchor" href="#针对-hugging-face-部署的更新方式" aria-label="Permalink to &quot;针对 Hugging Face 部署的更新方式&quot;">​</a></h2><ol><li>登录 Hugging Face，找到部署的 Space，点击上方 Settings，往下滚动找到并点击 Factory rebuild</li></ol><h2 id="针对私有部署的更新方式" tabindex="-1">针对私有部署的更新方式 <a class="header-anchor" href="#针对私有部署的更新方式" aria-label="Permalink to &quot;针对私有部署的更新方式&quot;">​</a></h2><ol><li>停止旧版本 <code>kill $(ps -ef | grep tkserver | grep -v &#39;grep&#39; | awk &#39;{print $2}&#39;)</code></li><li>拉取新版本 <code>npm i -g tkserver@latest</code></li><li>启动新版本 <code>nohup tkserver &gt;&gt; tkserver.log 2&gt;&amp;1 &amp;</code></li></ol><h2 id="针对私有部署-docker-的更新方式" tabindex="-1">针对私有部署 (Docker) 的更新方式 <a class="header-anchor" href="#针对私有部署-docker-的更新方式" aria-label="Permalink to &quot;针对私有部署 (Docker) 的更新方式&quot;">​</a></h2><ol><li>拉取新版本 <code>docker pull imaegoo/twikoo</code></li><li>停止旧版本容器 <code>docker stop twikoo</code></li><li>删除旧版本容器 <code>docker rm twikoo</code></li><li><a href="#私有部署-docker">启动新版本容器</a></li></ol><h2 id="自动更新" tabindex="-1">自动更新 <a class="header-anchor" href="#自动更新" aria-label="Permalink to &quot;自动更新&quot;">​</a></h2><p>考虑到可用性和安全性问题，Twikoo 没有实现自动更新，也没有计划实现自动更新。如果您希望实现自动更新，可以参考 MHuiG 基于 Github 工作流的 <a href="https://github.com/MHuiG/twikoo-update" target="_blank" rel="noreferrer">twikoo-update</a> 的实现方式。</p>`,26)])])}const u=o(l,[["render",s]]);export{h as __pageData,u as default};
